import math

def objective_function(x, y, z, w):
    return (x**4 + y**4 + z**4 + w**4) - 8 * (x**3 + y**3 + z**3 + w**3)

# Case 4: {3, 3, 3+sqrt(6), 3-sqrt(6)}
sqrt6 = math.sqrt(6)
b = 3 + sqrt6
c = 3 - sqrt6
set_4 = [3, 3, b, c]
f_4 = objective_function(*set_4)

print(f"f({set_4}): {f_4}")
